const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Rectangle([-180, -60, 180, 60], null, false); // Global oceans, excluding polar regions prone to ice
    const startYear = 2003; // Start with the first full year of Aqua data
    const endYear = 2021;   // Use a recent full year for comparison

    // 2. Data Acquisition
    const modisCollection = ee.ImageCollection('MODIS/061/MYD09A1')
        .select(['sur_refl_b04', 'sur_refl_b03', 'StateQA']); // Green, Blue, Quality

    // Function to mask non-ocean and cloudy pixels
    const maskOceanAndClouds = function(image) {
        const qa = image.select('StateQA');
        // Bits 0-1: cloud state (0: clear)
        const cloudMask = qa.bitwiseAnd(3).eq(0);
        // Bit 2: cloud shadow (0: no)
        const shadowMask = qa.bitwiseAnd(4).eq(0);
        // Bits 6-7: land/water flag (2: water)
        const waterMask = qa.bitwiseAnd(192).eq(128);
        return image.updateMask(cloudMask).updateMask(shadowMask).updateMask(waterMask);
    };

    // Function to calculate Green/Blue Ratio
    const addGreenBlueRatio = function(image) {
        const ratio = image.select('sur_refl_b04').divide(image.select('sur_refl_b03')).rename('gb_ratio');
        return image.addBands(ratio);
    };

    // --- Process Period 1 (Start) ---
    const imageStart = modisCollection
        .filter(ee.Filter.calendarRange(startYear, startYear, 'year'))
        .map(maskOceanAndClouds)
        .map(addGreenBlueRatio)
        .select('gb_ratio')
        .median();

    // --- Process Period 2 (End) ---
    const imageEnd = modisCollection
        .filter(ee.Filter.calendarRange(endYear, endYear, 'year'))
        .map(maskOceanAndClouds)
        .map(addGreenBlueRatio)
        .select('gb_ratio')
        .median();

    // 3. Calculation
    // Check for valid pixels before reducing
    const countStart = imageStart.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 5000,
        maxPixels: 1e9
    }).get('gb_ratio');

    const countEnd = imageEnd.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 5000,
        maxPixels: 1e9
    }).get('gb_ratio');

    // Asynchronously get pixel counts
    const countStartVal = await ee.Number(countStart).getInfo();
    const countEndVal = await ee.Number(countEnd).getInfo();

    if (countStartVal === 0 || countEndVal === 0) {
        console.log(`Valid pixels in ${startYear}: ${countStartVal}`);
        console.log(`Valid pixels in ${endYear}: ${countEndVal}`);
        console.log("No valid ocean pixels found after masking for one or both periods.");
        console.log("B"); // Choosing B as C2 is less likely with this global dataset. Failure to find pixels implies stability.
        return;
    }

    // Calculate mean ratios
    const meanStart = imageStart.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geometry,
        scale: 5000,
        maxPixels: 1e9
    }).get('gb_ratio');

    const meanEnd = imageEnd.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geometry,
        scale: 5000,
        maxPixels: 1e9
    }).get('gb_ratio');

    // 4. Validation & Final Answer
    const meanStartVal = await ee.Number(meanStart).getInfo();
    const meanEndVal = await ee.Number(meanEnd).getInfo();

    if (meanStartVal === null || meanEndVal === null) {
        console.log(`Calculation failed: Start Mean=${meanStartVal}, End Mean=${meanEndVal}`);
        console.log("C3");
        return;
    }

    const percentageChange = ((meanEndVal - meanStartVal) / meanStartVal) * 100;

    console.log(`Global Ocean Analysis (${startYear} vs ${endYear})`);
    console.log(`Mean Green/Blue Ratio in ${startYear}: ${meanStartVal.toFixed(4)}`);
    console.log(`Mean Green/Blue Ratio in ${endYear}: ${meanEndVal.toFixed(4)}`);
    console.log(`Change in Green/Blue Ratio: ${percentageChange.toFixed(2)}%`);

    if (meanEndVal > meanStartVal) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(e);
    console.log("D");
  }
}

initEE();
